add_action( 'template_redirect', 'perfectpixel_redirect_empty_category_pages' );

function perfectpixel_redirect_empty_category_pages() {
	if ( ! is_404() || (int) get_query_var( 'paged' ) < 2 ) {
		return;
	}
	foreach ( array( 'product_cat', 'product_tag' ) as $taxonomy ) {
		$slug = get_query_var( $taxonomy );
		if ( $slug ) {
			$term = get_term_by( 'slug', $slug, $taxonomy );
			if ( $term ) {
				wp_safe_redirect( get_term_link( $term ), 301 );
				exit;
			}
		}
	}
}
